import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline


# ---------- Kernel for naive matrix multiplication (float32) ----------
matmul_kernel = """
__global__ void matmul_kernel(const float* A, const float* B, float* C, int rows, int cols) {
    // Each thread computes one element of the output matrix C[row][col]
    int row = blockIdx.y * blockDim.y + threadIdx.y;
    int col = blockIdx.x * blockDim.x + threadIdx.x;
    if (row < rows && col < cols) {
        float sum = 0.0f;
        for (int k = 0; k < rows; ++k) { // assuming A is rows x cols
            sum += A[row * cols + k] * B[k * cols + col];
        }
        C[row * cols + col] = sum;
    }
}
"""

# ---------- Custom CUDA function for matrix multiplication ----------
matmul_cuda_source = """
torch::Tensor custom_matmul_cuda(torch::Tensor a, torch::Tensor b) {
    const int N = a.size(0);
    const int block_size = 256;
    const int num_blocks_rows = (N + block_size - 1) / block_size;
    const int num_blocks_cols = (N + block_size - 1) / block_size;

    // Allocate destination tensor on the same device
    auto out = torch::zeros_like(a);

    matmul_kernel<<<num_blocks_rows * num_blocks_cols, block_size, block_size>>>(a.data_ptr<float>(), b.data_ptr<float>(), out.data_ptr<float()>, N);
    return out;
}
"""

# Compile the custom matrix multiplication inline function
custom_matmul = load_inline(
    name="custom_matmul",
    cpp_sources=("torch::Tensor custom_matmul_cuda(torch::Tensor a, torch::Tensor b);"),
    cuda_sources=matmul_cuda_source,
    functions=["custom_matmul"],
    verbose=True,
    extra_cflags=[],
    extra_ldflags=[],
)

