    int rows = t.size(0);
    int cols = t.size(1);
    for (int i = 0; i < rows; ++i) {
        for (int j = 0; j < cols; ++j) {
            if (i <= j) out[i, j] = t[i, j];
            else out[i, j] = 0.0f;
